------------ import ------------
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local MazeMgr = import('Game.Maze.MazeMgr'):GetInstance()
local CanvasGroup = CS.UnityEngine.CanvasGroup

------------ import ------------

------------ define ------------
local SwitchImageStatus = {
    Default = 1,
    Lock = 3,
    Select = 2
}
local SwitchTextStatus = {
    Default = 1,
    Select = 2
}
local AlphaStatus = {
    Default = 0.3,
    Select = 1
}
------------ define ------------


---@class PatrolMainChooseCellNode
---@field AnimShow                      	UnityEngine.Animator
---@field AnimChoose                    	UnityEngine.Animator
---@field Text                          	UnityEngine.UI.Text
---@field ImgIcon                       	Engine.UI.ImageAlterable
---@field ImgFrame                      	Game.Native.Common.UISwitchImage
local PatrolMainChooseCellNode = Class("PatrolMainChooseCellNode")
function PatrolMainChooseCellNode:__init()
    self.btnAction = nil
    self.data = {}

end

function PatrolMainChooseCellNode:__delete()
    self.btnAction = nil
    self.data = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function PatrolMainChooseCellNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function PatrolMainChooseCellNode:Awake()
    self.EventEnterEvent = Events.AddListener(Constants.EventNames.PatrolEventEnter, Bind(self, self.FreshSelectStatus))
    self.EventEnterChoose = Events.AddListener(Constants.EventNames.PatrolEventChoose, Bind(self, self.PlayChooseAnim))

    SetButtonAction(self.controller, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)

end

function PatrolMainChooseCellNode:FreshBaseUI(data)
    self.data = data
    CfUtils.PlayDelayShowAnimate(self.AnimShow, self.data.index, 0.1, 0.5)
    self.Text.text = self.data.text
    self.ImgIcon:LoadSprite(self.data.iconPath)
    self:FreshSelectStatus()
end

function PatrolMainChooseCellNode:FreshSelectStatus()
    if isNull(self.data) then
        return
    end
    local isSelected = MazeMgr.currentPos > 0
    local status
    local statusText
    local statusAlpha
    if isSelected then
        local isSelectedThis = self.data.index == checkNumber(MazeMgr.currentPos)
        if isSelectedThis then
            statusText = SwitchTextStatus.Select
            status = SwitchImageStatus.Select
            statusAlpha = AlphaStatus.Select
        else
            status = SwitchImageStatus.Lock
            statusText = SwitchTextStatus.Default
            statusAlpha = AlphaStatus.Default
        end
    else
        status = SwitchImageStatus.Default
        statusText = SwitchTextStatus.Default
        statusAlpha = AlphaStatus.Select
    end
    self.ImgFrame.Status = status
    self.controller.gameObject:GetComponent(typeof(CanvasGroup)).alpha = statusAlpha
    CfUtils.SetUISwitchText(self.Text.transform, statusText)
end

function PatrolMainChooseCellNode:PlayChooseAnim(index)
    if isNull(index) then
        self.AnimChoose:Play("PatrolMainDialog_Btn")
        return
    end
    local isSelect = index == self.data.index
    self.AnimChoose:Play(isSelect and "Select" or "Exit")
end

function PatrolMainChooseCellNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.PatrolEventEnter, self.EventEnterEvent)
    Events.RemoveListener(Constants.EventNames.PatrolEventChoose, self.EventEnterChoose)

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PatrolMainChooseCellNode